{% extends "base.html" %}

{% block title %}
   Todolist Page
{% endblock title %}

{% block headline %}
  Welcome to {{page}}
{% endblock headline %}

{% block content %}

<div class="container">

  <!-- Add Task Card -->
  <div class="card shadow-lg p-4 mb-4">
    <h5 class="fw-bold mb-3">Add New Task</h5>

    <form method="post" class="d-flex gap-2">
      {% csrf_token %}
      <input type="text" class="form-control" name="task" placeholder="Enter your task..." required>
      <button type="submit" class="btn btn-primary">
        <i class="bi bi-plus-lg"></i>
      </button>
    </form>
  </div>

  <!-- Messages -->
  {% if messages %}
    {% for message in messages %}
      <div class="alert alert-warning alert-dismissible fade show" role="alert">
        {{ message }}
        <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
      </div>
    {% endfor %}
  {% endif %}

  <!-- Task List -->
  <div class="row g-3">

    {% for task in all_tasks %}

    <div class="col-md-6">
      <div class="card shadow-sm p-3 h-100 {% if task.isCompleted %}bg-light{% endif %}">

        <div class="d-flex justify-content-between align-items-center">

          <!-- Task Name -->
          <div>
            <h6 class="fw-bold mb-1 
              {% if task.isCompleted %}text-decoration-line-through text-muted{% endif %}">
              {{ task.task }}
            </h6>

            {% if task.isCompleted %}
              <span class="badge bg-success">Completed</span>
            {% else %}
              <span class="badge bg-warning text-dark">Pending</span>
            {% endif %}
          </div>

          <!-- Actions -->
          <div class="d-flex gap-2">

            {% if task.isCompleted %}
              <a href="{% url 'pending_task' task.id %}" class="btn btn-sm btn-secondary">
                <i class="bi bi-arrow-counterclockwise"></i>
              </a>
            {% else %}
              <a href="{% url 'complete_task' task.id %}" class="btn btn-sm btn-success">
                <i class="bi bi-check-lg"></i>
              </a>
            {% endif %}

            <a href="{% url 'edit_task' task.id %}" class="btn btn-sm btn-warning">
              <i class="bi bi-pencil"></i>
            </a>

            <a href="{% url 'delete_task' task.id %}" class="btn btn-sm btn-danger">
              <i class="bi bi-trash"></i>

def homepage(request):
    context ={
        'page': 'homepage'
    }
    return render(request, "main.html", context)

def todolist(request):
    if request.method == "POST":
        form_data =TaskForm(request.POST or None)
        if form_data.is_valid():
            form_data.save()
            messages.success(request, "Task Added Successfully")
            return redirect("todolist") 
        messages.success(request, "Something Went Wrong")

    all_tasks = Task.objects.all()
    paginator = Paginator(all_tasks, 8)
    page = request.GET.get("page")

    all_tasks = paginator.get_page(page)
    context ={
        'page': 'todolist',
        'all_tasks': all_tasks
     }
    return render(request, "todolist.html", context)

def delete_task(request, task_id):
    task_obj = Task.objects.get(id = task_id)
    task_obj.delete()
    messages.success(request,  f"Task- {task_obj.task} deleted.")
    return redirect("todolist")

def edit_task(request, task_id):
    task_obj = Task.objects.get(id= task_id)

    if request.method == "POST":
        form_data =TaskForm(request.POST or None, instance = task_obj)
        if form_data.is_valid():
            form_data.save()
            messages.success(request, "Task Updated Successfully")
            return redirect("todolist")
        messages.success(request, "Error Encountered in updation")
    else:
        context={
        'task_obj': task_obj
        }
        return render(request, "edit.html", context)

def complete_task(request, task_id):
    task_obj = Task.objects.get(id= task_id)
    task_obj.isCompleted = True
    task_obj.save()
    messages.success(request, "Status Changed Successfully")
    return redirect("todolist")

def pending_task(request, task_id):
    task_obj = Task.objects.get(id= task_id)
    task_obj.isCompleted = False
    task_obj.save()
    messages.success(request, "Status Changed Successfully")
    return redirect("todolist")

